const response = $input.first().json;
const statusCode = response.statusCode || response.$response?.statusCode || 0;
const responseTime = response.$response?.timings?.end || Date.now();
const isUp = statusCode === 200;

// Store result for daily summary
return [{
  json: {
    statusCode,
    isUp,
    url: 'https://demo.realworld.io',
    checkedAt: new Date().toISOString(),
    responseTimeMs: responseTime
  }
}];

// App is healthy — log silently, no alert needed
const d = $input.first().json;
console.log(`[UPTIME OK] ${d.url} responded ${d.statusCode} at ${d.checkedAt}`);
return [{ json: { status: 'ok', ...d } }];

// Build alert message for down/degraded state
const d = $input.first().json;
const alert = [
  '🚨 *UPTIME ALERT*',
  `URL: ${d.url}`,
  `Status: ${d.statusCode || 'NO RESPONSE (timeout/connection error)'}`,
  `Time: ${d.checkedAt}`,
  'ACTION REQUIRED: App may be down. Please investigate.'
].join('\n');
return [{ json: { alert, ...d } }];
